import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Installation","description":"Install GameFilter XDP from the release package — prerequisites, interactive install steps, post-install verification, troubleshooting, and uninstall.","frontmatter":{"title":"Installation","description":"Install GameFilter XDP from the release package — prerequisites, interactive install steps, post-install verification, troubleshooting, and uninstall."},"headers":[],"relativePath":"gamefilter-xdp/getting-started/installation.md","filePath":"gamefilter-xdp/getting-started/installation.md","lastUpdated":1787468851000}'),n={name:"gamefilter-xdp/getting-started/installation.md"};function o(l,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><blockquote><p><strong>Get GameFilter XDP validating game traffic in a few minutes.</strong> The release package ships pre-built binaries — no Rust toolchain, no build tools, nothing else to install. Root and a 5.15+ kernel with BTF are all you need.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#install-steps">Install Steps</a><ul><li><a href="#step-1-4-—-network-interface">Step 1/4 — Network Interface</a></li><li><a href="#step-2-4-—-deployment-mode">Step 2/4 — Deployment Mode</a></li><li><a href="#step-3-4-—-default-action">Step 3/4 — Default Action</a></li><li><a href="#step-4-4-—-management-api">Step 4/4 — Management API</a></li></ul></li><li><a href="#verification">Verification</a></li><li><a href="#troubleshooting">Troubleshooting</a><ul><li><a href="#error-failed-to-attach-xdp-operation-not-supported">Error: failed to attach XDP: Operation not supported</a></li><li><a href="#non-game-vps-traffic-broken-on-proxmox">Non-game VPS traffic broken on Proxmox</a></li></ul></li><li><a href="#uninstall">Uninstall</a></li></ul></nav><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum</th><th>Check</th></tr></thead><tbody><tr><td>Kernel</td><td>Linux <strong>5.15+</strong></td><td><code>uname -r</code></td></tr><tr><td>Kernel BTF</td><td><code>CONFIG_DEBUG_INFO_BTF=y</code></td><td><code>ls /sys/kernel/btf/vmlinux</code></td></tr><tr><td>Privileges</td><td>root</td><td><code>id -u</code> → <code>0</code></td></tr><tr><td>Topology</td><td>VM bridge (<code>vmbr0</code> / <code>br0</code>) or <strong>private NIC</strong> behind OpenShield</td><td><code>ip link</code></td></tr></tbody></table><p>The release package has <strong>no other dependencies</strong> — the XDP object (<code>gamefilter-ebpf.o</code>) and the userspace binary (<code>gamefilter</code>) are pre-built.</p><div class="warning custom-block"><p class="custom-block-title">BTF is not optional</p><p>The eBPF program is a CO-RE object and requires kernel BTF. If <code>/sys/kernel/btf/vmlinux</code> does not exist, the installer stops immediately. Virtually all modern distro kernels (Ubuntu 22.04+, Debian 12+, Fedora, Arch, Rocky/Alma 9+, Proxmox VE 7/8+) ship BTF enabled.</p></div><div class="tip custom-block"><p class="custom-block-title">OpenShield + GameFilter on the Same Host</p><p>Because Linux allows only one native XDP program per interface, run <a href="/pingless-studios-docs/openshield-xdp/">OpenShield-XDP</a> on your physical uplink (<code>eno1</code>) to absorb raw DDoS floods, and attach GameFilter to your internal VM bridge (<code>vmbr0</code> / <code>br0</code>) in <code>mode: dedicated</code>.</p></div><hr><h2 id="install-steps" tabindex="-1">Install Steps <a class="header-anchor" href="#install-steps" aria-label="Permalink to &quot;Install Steps&quot;">​</a></h2><p>Extract the release package and run the installer as root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-xdp-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter-xdp-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span></span></code></pre></div><p>The installer auto-detects your environment (Proxmox VE / Dedicated Bare Metal / KVM / VPS), checks kernel BTF, and guides you through 4 steps:</p><h3 id="step-1-4-—-network-interface" tabindex="-1">Step 1/4 — Network Interface <a class="header-anchor" href="#step-1-4-—-network-interface" aria-label="Permalink to &quot;Step 1/4 — Network Interface&quot;">​</a></h3><p>The installer lists all interfaces and highlights the recommended private interface or VM bridge (e.g. <code>vmbr0</code> on Proxmox).</p><h3 id="step-2-4-—-deployment-mode" tabindex="-1">Step 2/4 — Deployment Mode <a class="header-anchor" href="#step-2-4-—-deployment-mode" aria-label="Permalink to &quot;Step 2/4 — Deployment Mode&quot;">​</a></h3><p>Choose how GameFilter inspects traffic on the interface:</p><ul><li><strong><code>dedicated</code> (Multi-Tenant / Proxmox):</strong> ONLY enrolled tenant destination IPs are inspected. All other destination IPs on the bridge bypass filtering with <code>XDP_PASS</code> (100% safe for web, DB, and general guest VPSes).</li><li><strong><code>vps</code> (Single VPS / Standalone):</strong> Protects all destination IPs arriving on this interface.</li></ul><p>If <code>dedicated</code> is chosen, you can enter initial protected tenant IPs or enroll them later via API.</p><h3 id="step-3-4-—-default-action" tabindex="-1">Step 3/4 — Default Action <a class="header-anchor" href="#step-3-4-—-default-action" aria-label="Permalink to &quot;Step 3/4 — Default Action&quot;">​</a></h3><ul><li><code>pass</code> (Recommended for dedicated / mixed-use hosts): Ports not matching any filter on filtered IPs pass normally.</li><li><code>drop</code> (Strict shield for dedicated game interfaces): Drops unmatched ports.</li></ul><h3 id="step-4-4-—-management-api" tabindex="-1">Step 4/4 — Management API <a class="header-anchor" href="#step-4-4-—-management-api" aria-label="Permalink to &quot;Step 4/4 — Management API&quot;">​</a></h3><p>Enables the token-authenticated REST API on <code>127.0.0.1:9300</code> and generates an API key.</p><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Check that the filter is loaded:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GameFilter XDP is loaded.</span></span>
<span class="line"><span>  Interface: vmbr0 (native)  |  Mode: dedicated</span></span>
<span class="line"><span>  Packets: 48212 passed, 140023 dropped | validated ok 340 fail 139800 | admitted 47872 | banned 5</span></span>
<span class="line"><span>  Protected Tenants (2):</span></span>
<span class="line"><span>    • 10.210.0.2 (Minecraft VPS)</span></span>
<span class="line"><span>    • 10.210.0.3 (FiveM VPS)</span></span>
<span class="line"><span>  [ 0] mc-java        tcp ports=25565              pass=12000 drop=0</span></span>
<span class="line"><span>  [ 1] mc-bedrock     udp ports=19132              pass=8200  drop=140023</span></span>
<span class="line"><span>  [ 2] fivem          udp ports=30120              pass=28000 drop=0</span></span></code></pre></div><p>Verify the API daemon:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># prints API URL and key</span></span></code></pre></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="error-failed-to-attach-xdp-operation-not-supported" tabindex="-1"><code>Error: failed to attach XDP: Operation not supported</code> <a class="header-anchor" href="#error-failed-to-attach-xdp-operation-not-supported" aria-label="Permalink to &quot;\`Error: failed to attach XDP: Operation not supported\`&quot;">​</a></h3><p>Your NIC or bridge driver does not support native XDP (<code>DRV_MODE</code>). The loader automatically falls back to generic XDP (<code>SKB_MODE</code>).</p><h3 id="non-game-vps-traffic-broken-on-proxmox" tabindex="-1"><code>Non-game VPS traffic broken on Proxmox</code> <a class="header-anchor" href="#non-game-vps-traffic-broken-on-proxmox" aria-label="Permalink to &quot;\`Non-game VPS traffic broken on Proxmox\`&quot;">​</a></h3><p>Make sure you are running <code>mode: dedicated</code> in <code>/etc/gamefilter/gamefilter.yaml</code>. In <code>dedicated</code> mode, un-enrolled VPS IPs bypass filtering completely.</p><hr><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # keep configuration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --purge</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # remove binaries, systemd units, and /etc/gamefilter</span></span></code></pre></div>`,40)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
